		stg.[VENDORVATDATE],
		stg.[VENDPAYMFEEGROUP_JP],
		stg.[VENDTRANSID],
		stg.[VOUCHER],
		stg.[VOUCHER_CN]	
	FROM [staging_fo].[LEDGERJOURNALTRANS] stg
		LEFT JOIN [synapse_fo].[LEDGERJOURNALTRANS] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
